1	// Anthropic Messages API wrapper — used by both the "Build with Claude AI"
2	// BYOK feature and the live-chat agent (lib/kb-llm.ts). Built on the official
3	// @anthropic-ai/sdk rather than raw fetch. Every export below (types,
4	// function names, signatures, thrown-error shape) is unchanged from the prior
5	// fetch-based version, so no caller needed to change.
6	
7	import Anthropic from "@anthropic-ai/sdk";
8	import { decryptSecret } from "./crypto-box";
9	
10	const MODEL = "claude-opus-4-8";
11	
12	/** One client per API key — callers pass a different key per request (BYOK),
13	 *  so this avoids constructing a new client (and re-validating env) on every
14	 *  call within a hot loop while still never caching across different keys. */
15	const clients = new Map<string, Anthropic>();
16	function clientFor(apiKey: string): Anthropic {
17	  let c = clients.get(apiKey);
18	  if (!c) {
19	    c = new Anthropic({ apiKey });
20	    clients.set(apiKey, c);
21	  }
22	  return c;
23	}
24	
25	/** Rethrow SDK errors in the same `Error` shape callers already handle
26	 *  (they only ever read `.message`, never match on it structurally). */
27	function wrapApiError(e: unknown): Error {
28	  if (e instanceof Anthropic.APIError) {
29	    const detail = typeof e.error === "object" ? JSON.stringify(e.error) : String(e.message);
30	    return new Error(`Anthropic API ${e.status}: ${detail.slice(0, 500)}`);
31	  }
32	  return e instanceof Error ? e : new Error(String(e));
33	}
34	
35	/** Content block shapes accepted by the Messages API. `content` may be a plain
36	 *  string, or an array mixing text and (for vision) base64 image blocks. */
37	export type ClaudeTextBlock = { type: "text"; text: string };
38	export type ClaudeImageBlock = {
39	  type: "image";
40	  source: { type: "base64"; media_type: string; data: string };
41	};
42	export type ClaudeContent = string | Array<ClaudeTextBlock | ClaudeImageBlock>;
43	export type ClaudeMessage = { role: "user" | "assistant"; content: ClaudeContent };
44	
45	/** True when an optional platform-wide fallback key is configured. */
46	export function platformKeyConfigured(): boolean {
47	  return Boolean(process.env.ANTHROPIC_API_KEY && process.env.ANTHROPIC_API_KEY.trim());
48	}
49	
50	/** Deprecated alias kept for backwards compatibility. */
51	export function anthropicConfigured(): boolean {
52	  return platformKeyConfigured();
53	}
54	
55	/**
56	 * Resolve the effective key for a user: their own decrypted BYOK key if present,
57	 * otherwise the optional platform-wide ANTHROPIC_API_KEY. Returns null if neither
58	 * is available. Never throws on a bad/absent stored key (decryptSecret returns null).
59	 */
60	export function effectiveKeyFor(
61	  user: { anthropicKeyEnc?: string | null } | null | undefined
62	): string | null {
63	  const own = decryptSecret(user?.anthropicKeyEnc ?? null);
64	  if (own && own.trim()) return own.trim();
65	  const platform = process.env.ANTHROPIC_API_KEY;
66	  return platform && platform.trim() ? platform.trim() : null;
67	}
68	
69	/**
70	 * Send a chat turn to Claude and return the concatenated text of the reply.
71	 * The caller supplies the API key (the build owner's effective key).
72	 * Throws when the key is missing or the API returns a non-2xx response.
73	 */
74	export async function askClaude(
75	  apiKey: string,
76	  messages: ClaudeMessage[],
77	  system: string,
78	  opts: { maxTokens?: number; timeoutMs?: number; model?: string } = {}
79	): Promise<string> {
80	  if (!apiKey) throw new Error("No Anthropic API key available");
81	
82	  let data: Anthropic.Message;
83	  try {
84	    data = await clientFor(apiKey).messages.create(
85	      {
86	        model: opts.model ?? MODEL,
87	        max_tokens: opts.maxTokens ?? 1024,
88	        system,
89	        messages: messages as Anthropic.MessageParam[],
90	      },
91	      { timeout: opts.timeoutMs ?? 60_000 }
92	    );
93	  } catch (e) {
94	    throw wrapApiError(e);
95	  }
96	
97	  return data.content
98	    .filter((b): b is Anthropic.TextBlock => b.type === "text")
99	    .map((b) => b.text)
100	    .join("")
101	    .trim();
102	}
103	
104	/** A tool the model can call. `input_schema` is a JSON Schema object. */
105	export type ClaudeToolDef = {
106	  name: string;
107	  description: string;
108	  input_schema: Record<string, unknown>;
109	};
110	
111	type AnyBlock = { type: string; text?: string; id?: string; name?: string; input?: unknown };
112	type AnyMsg = { role: "user" | "assistant"; content: unknown };
113	
114	/**
115	 * Agentic Messages call: give the model tools, run the look-up→reason loop
116	 * (execute each tool_use, feed the result back) until it produces a final
117	 * answer or the round cap is hit. `execTool` runs YOUR scoped, read-only tool
118	 * and returns a string for the model. Returns the model's final text.
119	 */
120	export async function askClaudeWithTools(
121	  apiKey: string,
122	  opts: {
123	    system: string;
124	    messages: ClaudeMessage[];
125	    tools: ClaudeToolDef[];
126	    execTool: (name: string, input: unknown) => Promise<string>;
127	    model?: string;
128	    maxTokens?: number;
129	    timeoutMs?: number;
130	    maxRounds?: number;
131	  },
132	): Promise<string> {
133	  if (!apiKey) throw new Error("No Anthropic API key available");
134	  const msgs: AnyMsg[] = [...(opts.messages as AnyMsg[])];
135	  const rounds = opts.maxRounds ?? 4;
136	  const client = clientFor(apiKey);
137	
138	  for (let i = 0; i < rounds; i++) {
139	    let data: Anthropic.Message;
140	    try {
141	      data = await client.messages.create(
142	        {
143	          model: opts.model ?? MODEL,
144	          max_tokens: opts.maxTokens ?? 600,
145	          system: opts.system,
146	          tools: opts.tools as Anthropic.Tool[],
147	          messages: msgs as Anthropic.MessageParam[],
148	        },
149	        { timeout: opts.timeoutMs ?? 26_000 }
150	      );
151	    } catch (e) {
152	      throw wrapApiError(e);
153	    }
154	    const content = data.content as AnyBlock[];
155	
156	    if (data.stop_reason !== "tool_use") {
157	      return content
158	        .filter((b) => b.type === "text" && typeof b.text === "string")
159	        .map((b) => b.text as string)
160	        .join("")
161	        .trim();
162	    }
163	
164	    // Execute every requested tool, then feed all results back in one user turn.
165	    msgs.push({ role: "assistant", content });
166	    const toolResults: Array<{ type: "tool_result"; tool_use_id: string; content: string }> = [];
167	    for (const block of content) {
168	      if (block.type === "tool_use" && block.id && block.name) {
169	        let out: string;
170	        try {
171	          out = await opts.execTool(block.name, block.input);
172	        } catch (e) {
173	          out = `Error running ${block.name}: ${e instanceof Error ? e.message : "failed"}`;
174	        }
175	        toolResults.push({ type: "tool_result", tool_use_id: block.id, content: out.slice(0, 8000) });
176	      }
177	    }
178	    msgs.push({ role: "user", content: toolResults });
179	  }
180	
181	  // Round cap hit — ask once more for a plain answer with no further tools.
182	  return askClaude(apiKey, msgs as ClaudeMessage[], opts.system, {
183	    model: opts.model,
184	    maxTokens: opts.maxTokens ?? 600,
185	    timeoutMs: opts.timeoutMs,
186	  });
187	}
