1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { trustedClientIp } from "@/app/api/_lib/client-ip";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	import { readTyping } from "@/lib/chat-typing";
8	
9	export const runtime = "nodejs";
10	
11	/**
12	 * Public live-chat endpoint used by <ChatWidget/>.
13	 *
14	 * POST /api/chat  — start or continue a conversation for a visitorId.
15	 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
16	 *
17	 * Everything is scoped strictly by the client-supplied `visitorId`; we never
18	 * return another visitor's data. Signed-in customers additionally get their
19	 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
20	 * POST path is rate-limited per IP.
21	 */
22	
23	function clip(v: unknown, max: number): string | null {
24	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
25	}
26	
27	type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;
28	
29	function serialize(convo: {
30	  id: string;
31	  status: string;
32	  name: string | null;
33	  email: string | null;
34	  messages: {
35	    id: string;
36	    sender: string;
37	    body: string;
38	    cardsJson?: string | null;
39	    createdAt: Date;
40	    attachment?: AttachmentRow;
41	  }[];
42	}) {
43	  return {
44	    conversation: {
45	      id: convo.id,
46	      status: convo.status,
47	      name: convo.name,
48	      email: convo.email,
49	    },
50	    messages: convo.messages.map((m) => {
51	      let cards: unknown = null;
52	      if (m.cardsJson) {
53	        try {
54	          cards = JSON.parse(m.cardsJson);
55	        } catch {
56	          cards = null;
57	        }
58	      }
59	      return {
60	        id: m.id,
61	        sender: m.sender,
62	        body: m.body,
63	        createdAt: m.createdAt.toISOString(),
64	        cards,
65	        attachment: m.attachment
66	          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
67	          : null,
68	      };
69	    }),
70	  };
71	}
72	
73	export async function POST(req: Request) {
74	  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
75	  if (!rl.ok) {
76	    return NextResponse.json(
77	      { error: "Too many messages. Please slow down." },
78	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
79	    );
80	  }
81	
82	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
83	  const visitorId = clip(raw.visitorId, 100);
84	  const conversationId = clip(raw.conversationId, 40);
85	  const body = clip(raw.body, 5000);
86	  const name = clip(raw.name, 120);
87	  const email = clip(raw.email, 200);
88	
89	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
90	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
91	
92	  const user = await currentUser();
93	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
94	    user?.id ? [{ userId: user.id }] : [],
95	  );
96	
97	  // If the client names a conversation it owns, continue it (resuming past
98	  // history, reopening if it was closed). Otherwise start a brand-new one — we
99	  // no longer auto-resume the latest, so returning gives a fresh chat while old
100	  // threads stay available in the history list.
101	  let convo = conversationId
102	    ? await db.chatConversation.findFirst({
103	        where: { id: conversationId, OR: ownedBy },
104	        select: { id: true, name: true, email: true },
105	      })
106	    : null;
107	
108	  if (!convo) {
109	    // Anonymous (not signed in) visitors must give a name + valid email before
110	    // starting. Signed-in customers already have both, so they're never asked.
111	    if (!user) {
112	      const nm = name ?? null;
113	      const em = email ?? null;
114	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
115	        return NextResponse.json(
116	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
117	          { status: 400 },
118	        );
119	      }
120	    }
121	    convo = await db.chatConversation.create({
122	      data: {
123	        visitorId,
124	        userId: user?.id ?? null,
125	        name: name ?? user?.name ?? null,
126	        email: email ?? user?.email ?? null,
127	      },
128	      select: { id: true, name: true, email: true },
129	    });
130	  }
131	
132	  await db.$transaction([
133	    db.chatMessage.create({
134	      data: { conversationId: convo.id, sender: "visitor", body },
135	    }),
136	    db.chatConversation.update({
137	      where: { id: convo.id },
138	      data: {
139	        status: "OPEN", // reopen if the visitor is resuming a closed thread
140	        unreadForAgent: true,
141	        lastMessageAt: new Date(),
142	        // Backfill identity / link account if it arrives after creation.
143	        ...(user?.id ? { userId: user.id } : {}),
144	        ...(name && !convo.name ? { name } : {}),
145	        ...(email && !convo.email ? { email } : {}),
146	      },
147	    }),
148	  ]);
149	
150	  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
151	  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
152	  // human has engaged.
153	  try {
154	    const { runAssistant } = await import("@/lib/kb-run");
155	    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
156	  } catch {
157	    /* assistant is non-essential — never fail the visitor's message on it */
158	  }
159	
160	  const full = await db.chatConversation.findUnique({
161	    where: { id: convo.id },
162	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
163	  });
164	  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
165	}
166	
167	export async function GET(req: Request) {
168	  const url = new URL(req.url);
169	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
170	  const conversationId = clip(url.searchParams.get("conversationId"), 40);
171	  if (!visitorId) {
172	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
173	  }
174	
175	  const user = await currentUser();
176	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
177	    user?.id ? [{ userId: user.id }] : [],
178	  );
179	
180	  // Poll a specific conversation when named (scoped to the visitor/user), else
181	  // the most recent open thread for back-compat.
182	  let convo = conversationId
183	    ? await db.chatConversation.findFirst({
184	        where: { id: conversationId, OR: ownedBy },
185	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
186	      })
187	    : await db.chatConversation.findFirst({
188	        where: { visitorId, status: "OPEN" },
189	        orderBy: { lastMessageAt: "desc" },
190	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
191	      });
192	
193	  if (!convo) {
194	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
195	  }
196	
197	  // If the bot is waiting on a live agent, let the poll drive the handoff window:
198	  // post the "no agents available" fallback once it elapses, then refresh so the
199	  // visitor sees it on this same poll rather than the next one.
200	  if (convo.botEscalatedAt) {
201	    try {
202	      const { checkEscalationTimeout } = await import("@/lib/kb-run");
203	      await checkEscalationTimeout(convo.id);
204	      const refreshed = await db.chatConversation.findFirst({
205	        where: { id: convo.id },
206	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
207	      });
208	      if (refreshed) convo = refreshed;
209	    } catch {
210	      /* non-essential */
211	    }
212	  }
213	
214	  // Reading the thread clears the visitor-facing unread flag.
215	  if (convo.unreadForUser) {
216	    await db.chatConversation
217	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
218	      .catch(() => {});
219	  }
220	
221	  // The whole support transcript, plus the name/email the visitor gave. The
222	  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
223	  // itself the secret — precisely the shape a shared cache must never store.
224	  //
225	  // `typing.agent` tells the widget whether a support agent is composing a reply
226	  // right now; it self-expires, so a stale poll can only ever under-report.
227	  return NextResponse.json(
228	    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent } },
229	    { headers: NO_STORE_HEADERS },
230	  );
231	}
