1	import "server-only";
2	import { decryptSecret } from "@/lib/crypto-box";
3	import { getSetting } from "@/lib/settings";
4	import { askClaudeWithTools, type ClaudeMessage, type ClaudeContent } from "@/lib/anthropic";
5	import { KB_SYSTEM, KB_PAGES } from "@/lib/kb-system";
6	import { chatToolsFor, runChatTool } from "@/lib/kb-tools";
7	import { PLAN_KEYS_FOR_PROMPT } from "@/lib/kb-plans";
8	
9	/** The default model for the chat agent when the admin setting is blank. A
10	 *  flagship agent that reasons across multiple tool calls; the admin can point
11	 *  kb_bot_model at a cheaper (haiku) or stronger (opus) model at any time. */
12	const DEFAULT_BOT_MODEL = "claude-sonnet-4-6";
13	
14	/**
15	 * Result of an agent turn. `ok` carries the final text. On failure we say WHY so
16	 * the caller can degrade gracefully AND surface real outages to the operator
17	 * (reason "error") instead of silently falling back — the exact failure mode that
18	 * previously let a dead key dump blog snippets at customers for a day.
19	 */
20	export type LlmResult =
21	  | { ok: true; text: string }
22	  | { ok: false; reason: "no_key" | "empty" | "error"; detail?: string };
23	
24	/**
25	 * Claude-powered brain for the live-chat assistant.
26	 *
27	 * The retrieval index (lib/kb.ts → kbSearch) still runs, but only to fetch the
28	 * most relevant FAQ/blog snippets; those plus the always-on operator knowledge
29	 * base (lib/kb-system.ts) are handed to Claude as its SOLE source of truth. The
30	 * system prompt forbids inventing prices, plans, specs, SLAs, or coupon codes —
31	 * so the bot stays grounded while sounding human and steering toward a signup.
32	 *
33	 * Supports vision: pasted/attached images are passed to the model so it can help
34	 * with screenshots (errors, dashboards, designs). Model + key + coupon are admin
35	 * settings; if no key is configured, resolveBotKey() returns null and the caller
36	 * falls back to the token-free retrieval answer.
37	 */
38	
39	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
40	
41	export type LlmChunk = { title: string; snippet: string; url: string | null };
42	export type LlmImage = { mediaType: string; dataB64: string };
43	
44	/** The effective API key: the encrypted admin setting, else the platform env var. */
45	export async function resolveBotKey(): Promise<string | null> {
46	  const enc = await getSetting("kb_bot_api_key", "");
47	  const own = decryptSecret(enc || null);
48	  if (own && own.trim()) return own.trim();
49	  const platform = process.env.ANTHROPIC_API_KEY;
50	  return platform && platform.trim() ? platform.trim() : null;
51	}
52	
53	/** The canonical page map, rendered for the prompt so links are always real. */
54	function pageMap(): string {
55	  if (!KB_PAGES?.length) return "";
56	  return (
57	    "PAGES YOU CAN LINK TO (use the EXACT path, prefixed with the base URL; never link a path not in this list):\n" +
58	    KB_PAGES.map((p) => `- ${APP_URL}${p.path} — ${p.title}: ${p.desc}`).join("\n")
59	  );
60	}
61	
62	function buildSystem(coupon: string, visitorName: string | null, accountAware: boolean): string {
63	  const toolsBlock = accountAware
64	    ? "TOOLS — YOU ARE AN AGENT, NOT A FAQ. Before you answer anything factual, USE YOUR TOOLS; never guess when a tool can tell you the truth. THIS VISITOR IS A SIGNED-IN NXEON CUSTOMER, so you can look up THEIR OWN account. Playbook:\n" +
65	      "  • 'my server/site is down / not working / not running' → call check_platform_status AND list_services / get_service to find the specific service and its real status (RUNNING/STOPPED/SUSPENDED/ERROR, dunning, last error), THEN explain what's actually wrong and the fix. Do not answer generically.\n" +
66	      "  • billing / 'why was I charged' / 'is my payment ok' → get_billing_status and list_invoices.\n" +
67	      "  • pricing / 'which plan' → get_plans (authoritative prices) before quoting anything.\n" +
68	      "  • a specific how-to the core KB doesn't fully cover → search_help.\n" +
69	      "  • something that genuinely needs the human team or an action you can't do (a failed/ERROR provision, a refund, a real bug) → confirm with the customer, then open_support_ticket with the context you gathered.\n" +
70	      "You can READ everything but you can only WRITE by opening a support ticket — you cannot yourself restart a server, issue a refund, cancel, or change settings. When an action is needed, say plainly what you found and either point them to the exact dashboard control or open a ticket. Never reference any account but this customer's, and never invent account details a tool didn't return."
71	    : "TOOLS — YOU ARE AN AGENT, NOT A FAQ. Before answering anything factual, USE YOUR TOOLS: get_plans for real prices/specs, check_platform_status when someone reports something down or asks about an outage, search_help for specific how-tos. This visitor is NOT signed in, so you cannot see any account. If they ask about THEIR account/server/billing (e.g. 'my server is down'), first check_platform_status for a platform-wide incident, then ask them to sign in at /login so their account details are available in chat — don't guess about their specific service.";
72	  const accountBlock = "";
73	  const promo =
74	    "PROMOTION (always true right now): the first month of SHARED HOSTING is completely free — the visitor starts a plan, gets their site online, and is only billed from month two. This is hosting-only (it does not apply to VPS, game servers, domains, or email). Longer/annual terms are discounted.";
75	  const couponLine = coupon.trim()
76	    ? `ACTIVE COUPON: the code "${coupon.trim()}" gives a real discount at checkout. Offer it by name when the visitor shows buying intent, asks about deals/discounts, or is on the fence — present it as a little extra to help them start today.`
77	    : `No extra coupon code is active right now. When asked about deals, lean on the free-first-month promo and discounted longer terms — do NOT invent a coupon code.`;
78	  const nameLine = visitorName
79	    ? `The visitor's name is ${visitorName}. Use it naturally once or twice — don't overdo it.`
80	    : "";
81	
82	  return [
83	    "You are the Nxeon Assistant — the warm, sharp AI concierge on the live chat at nxeon.cloud, an all-in-one cloud hosting company (shared hosting, VPS, game servers, domains, business email, a website builder, and free migrations).",
84	    "",
85	    "YOUR JOB: genuinely help the visitor AND move them toward signing up for the right Nxeon product. Be a helpful salesperson, not a pushy one: answer their question well, then make the natural next step obvious.",
86	    nameLine,
87	    "",
88	    "VOICE — THIS MATTERS MOST: talk like a real person in a live chat, not a brochure or an FAQ. Keep replies SHORT — usually 1 to 3 sentences, the way you'd actually text someone. Have a real back-and-forth: when you need one more detail to give the right answer, ask a single quick question instead of dumping everything at once. Do NOT paste long paragraphs, bulleted lists, or multiple links. Never sign your messages (no '— Nxeon Assistant'), never repeat a canned closing line, and never restate what you already said. Mirror the visitor's tone and language; a little warmth and personality is good.",
89	    "GOOD length/feel: “For a single WordPress site, our Starter shared plan is perfect — $2.99/mo and the first month's free. Want the link to spin it up?” — short, specific, one question. Aim for that, not a wall of text.",
90	    "",
91	    "GROUNDING — HARD RULE: answer ONLY using the KNOWLEDGE BASE and RETRIEVED CONTEXT below. Never invent or guess prices, plan names, specs, limits, uptime numbers, SLAs, refund terms, or coupon codes. If the answer isn't in what you were given, say you're not 100% sure and ask a clarifying question rather than guessing — never make something up.",
92	    "",
