1	/**
2	 * Transient "typing…" signals for the live chat, kept in memory.
3	 *
4	 * This is a presence hint, not durable state: it never touches the database, it
5	 * expires on its own after `TYPING_TTL_MS`, and — exactly like `lib/rate-limit.ts`
6	 * — it lives in a module-level Map. On a horizontally-scaled deployment each
7	 * instance tracks independently; that is acceptable for a best-effort indicator,
8	 * and this app runs single-process. A signal that is never refreshed simply
9	 * ages out, so a crashed tab or a dropped connection can never leave a stuck
10	 * "typing" showing forever.
11	 *
12	 * Two directions per conversation:
13	 *   - visitor typing → surfaced to the agent (admin inbox)
14	 *   - agent typing   → surfaced to the visitor (ChatWidget)
15	 */
16	
17	export const TYPING_TTL_MS = 6000;
18	
19	export type TypingWho = "visitor" | "agent";
20	type Signal = { visitorAt?: number; agentAt?: number };
21	
22	const local = new Map<string, Signal>();
23	
24	// Persist across HMR / route reloads in dev so a signal isn't lost on every edit.
25	const globalForTyping = globalThis as unknown as { __nxeonChatTyping?: Map<string, Signal> };
26	const store: Map<string, Signal> = globalForTyping.__nxeonChatTyping ?? local;
27	if (process.env.NODE_ENV !== "production") globalForTyping.__nxeonChatTyping = store;
28	
29	/**
30	 * Is a timestamp still "live" — i.e. within `ttl` of `now`? Pure and total:
31	 * an absent/zero/future-garbage timestamp is never active. This is the single
32	 * predicate the whole expiry behaviour is built on, so it is exported for tests.
33	 */
34	export function isTypingActive(lastAt: number | undefined, now: number = Date.now(), ttl: number = TYPING_TTL_MS): boolean {
35	  return typeof lastAt === "number" && lastAt > 0 && now - lastAt >= 0 && now - lastAt < ttl;
36	}
37	
38	/** Record that `who` is currently typing in `conversationId`. */
39	export function markTyping(conversationId: string, who: TypingWho, now: number = Date.now()): void {
40	  if (!conversationId) return;
41	  const cur = store.get(conversationId) ?? {};
42	  if (who === "visitor") cur.visitorAt = now;
43	  else cur.agentAt = now;
44	  store.set(conversationId, cur);
45	  prune(now);
46	}
47	
48	/** Current typing state for a conversation, after expiry is applied. */
49	export function readTyping(conversationId: string, now: number = Date.now()): { visitor: boolean; agent: boolean } {
50	  const cur = store.get(conversationId);
51	  if (!cur) return { visitor: false, agent: false };
52	  return {
53	    visitor: isTypingActive(cur.visitorAt, now),
54	    agent: isTypingActive(cur.agentAt, now),
55	  };
56	}
57	
58	/** Drop conversations whose signals have all expired, bounding the Map. */
59	function prune(now: number): void {
60	  for (const [id, sig] of store) {
61	    if (!isTypingActive(sig.visitorAt, now) && !isTypingActive(sig.agentAt, now)) {
62	      store.delete(id);
63	    }
64	  }
65	}
66	
67	/** Test-only: clear all signals so suites don't leak state into each other. */
68	export function _resetTyping(): void {
69	  store.clear();
70	}
