2	import { db } from "@/lib/db";
3	import { getSetting, getSettingInt } from "@/lib/settings";
4	import { kbAnswer } from "@/lib/kb";
5	import { getPlanCards } from "@/lib/kb-plans";
6	import type { LlmImage } from "@/lib/kb-llm";
7	import type { ClaudeMessage } from "@/lib/anthropic";
8	import { sendMail, mailConfigured, layout, button } from "@/lib/mailer";
9	
10	/**
11	 * Assistant orchestrator shared by POST /api/chat and /api/chat/upload.
12	 *
13	 * Owns the "should the bot speak, and how" policy so both entry points behave
14	 * identically: enablement + human-present gating, the per-conversation and
15	 * daily guardrails, the Claude answer, and the live-agent HANDOFF flow —
16	 * escalate → email an agent → open a window → if no agent joins in time, post
17	 * the "no agents available" fallback (checkEscalationTimeout, also called from
18	 * the GET poll so it fires even when the visitor sends nothing more).
19	 *
20	 * Everything here is best-effort: a throw must never break the visitor's message.
21	 */
22	
23	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
24	const ADMIN_CHAT_URL = `${APP_URL}/admin/chat`;
25	
26	const WAIT_MSG =
27	  "Let me get a teammate for you — one moment while I see who's available. 👋";
28	const NO_AGENT_MSG =
29	  "Sorry — none of our team are free to jump in this second. I'm happy to keep helping you right here, or I can have someone personally reach out (usually within one business day). If you'd like a callback, just drop your email and a note and I'll pass it along.";
30	
31	function esc(s: string): string {
32	  return s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] as string);
33	}
34	
35	function firstName(name: string | null): string | null {
36	  const n = (name ?? "").trim();
37	  if (!n) return null;
38	  return n.split(/\s+/)[0].slice(0, 40);
39	}
40	
41	/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
42	 *  the visible body (directive stripped) and the card keys. */
43	function parseCardDirective(reply: string): { body: string; keys: string[] } {
44	  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
45	  if (!m) return { body: reply, keys: [] };
46	  const keys = m[1]
47	    .split(",")
48	    .map((s) => s.trim())
49	    .filter(Boolean);
50	  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
51	  return { body, keys };
52	}
53	
54	function toHistory(rows: { sender: string; body: string }[]): ClaudeMessage[] {
55	  return rows
56	    .filter((m) => m.body && m.body.trim())
57	    .map((m) => ({
58	      role: (m.sender === "visitor" ? "user" : "assistant") as "user" | "assistant",
59	      content: m.body,
60	    }));
61	}
62	
63	type ConvoLite = {
64	  id: string;
65	  visitorId: string;
66	  name: string | null;
67	  email: string | null;
68	};
69	
70	/** Atomically move the conversation into the "waiting for a live agent" state,
71	 *  post the holding message, and email an agent. No-op if already escalated. */
72	async function escalate(convo: ConvoLite, lastBody: string): Promise<void> {
73	  const claim = await db.chatConversation.updateMany({
74	    where: { id: convo.id, botEscalatedAt: null },
75	    data: { botEscalatedAt: new Date(), unreadForAgent: true },
76	  });
77	  if (claim.count !== 1) return; // someone/something already escalated
78	
79	  await db.chatMessage.create({
80	    data: { conversationId: convo.id, sender: "bot", body: WAIT_MSG },
81	  });
82	
83	  // Email an available agent (best-effort). They have the window to jump in.
84	  try {
85	    if (await mailConfigured()) {
86	      const to = (await getSetting("kb_bot_agent_email", "")) || (await getSetting("support_email", ""));
87	      if (to) {
88	        const who = convo.name
89	          ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
90	          : convo.email || "A website visitor";
91	        const html = layout(
92	          "A visitor wants to talk to a human",
93	          `<p><strong>${esc(who)}</strong> is asking for a live agent in the website chat.</p>
94	           <p style="color:#64748b">Latest message: “${esc(lastBody.slice(0, 300))}”</p>
95	           <p>Hop in within the next few minutes to take over — after that they'll be offered a callback instead.</p>
96	           ${button(ADMIN_CHAT_URL, "Open the live chat inbox")}`,
97	        );
98	        await sendMail({
99	          to,
100	          subject: "🔔 Live chat — a visitor wants a human",
101	          html,
102	          replyTo: convo.email || undefined,
103	        });
104	      }
105	    }
106	  } catch {
107	    /* email is best-effort; the conversation is already flagged in the inbox */
108	  }
109	}
110	
111	/**
112	 * If a conversation is waiting on a human and the window has elapsed with no
113	 * agent, post the "no agents available" fallback and clear the waiting state.
114	 * Atomic (updateMany claim) so concurrent polls can't double-post. Safe to call
115	 * on every message and every GET poll.
116	 */
117	export async function checkEscalationTimeout(conversationId: string): Promise<void> {
118	  try {
119	    const convo = await db.chatConversation.findUnique({
120	      where: { id: conversationId },
121	      select: { id: true, botEscalatedAt: true, assignedToId: true },
122	    });
123	    if (!convo?.botEscalatedAt) return;
124	
125	    // An agent joined (assigned or replied) — drop the waiting state, no fallback.
126	    const agentReplies = await db.chatMessage.count({
127	      where: { conversationId, sender: "agent" },
128	    });
129	    if (agentReplies > 0 || convo.assignedToId) {
130	      await db.chatConversation.updateMany({
131	        where: { id: conversationId, botEscalatedAt: { not: null } },
132	        data: { botEscalatedAt: null },
133	      });
134	      return;
135	    }
136	
137	    const windowSec = await getSettingInt("kb_bot_window_sec", 180);
138	    const threshold = new Date(Date.now() - windowSec * 1000);
139	    // Claim the timeout: only one caller wins, and only once the window passed.
140	    const claim = await db.chatConversation.updateMany({
141	      where: { id: conversationId, botEscalatedAt: { not: null, lte: threshold }, assignedToId: null },
142	      data: { botEscalatedAt: null },
143	    });
144	    if (claim.count !== 1) return;
145	
146	    await db.chatMessage.create({
147	      data: { conversationId, sender: "bot", body: NO_AGENT_MSG },
148	    });
149	  } catch {
150	    /* non-essential */
151	  }
152	}
153	
154	/**
155	 * Evaluate the assistant for a just-received visitor message. Creates a bot
156	 * reply (or runs the handoff flow) when appropriate. `images` are the base64
157	 * blocks for an image the visitor just sent (upload path), if any.
158	 */
159	export async function runAssistant(args: {
160	  conversationId: string;
161	  visitorId: string;
162	  currentBody: string;
163	  images?: LlmImage[];
164	}): Promise<void> {
165	  try {
166	    if ((await getSetting("kb_bot_enabled", "false")) !== "true") return;
167	
168	    const convo = await db.chatConversation.findUnique({
169	      where: { id: args.conversationId },
170	      select: {
171	        id: true,
172	        visitorId: true,
173	        userId: true,
174	        name: true,
175	        email: true,
176	        assignedToId: true,
177	        botEscalatedAt: true,
178	        messages: { orderBy: { createdAt: "asc" }, select: { sender: true, body: true } },
179	      },
180	    });
181	    if (!convo) return;
182	
183	    // Never talk over a human: silent once an agent replied or was assigned.
184	    const agentReplied = convo.messages.some((m) => m.sender === "agent");
185	    if (agentReplied || convo.assignedToId) return;
186	
187	    // Already waiting on a live agent — stay quiet; just check the timeout.
188	    if (convo.botEscalatedAt) {
189	      await checkEscalationTimeout(convo.id);
190	      return;
191	    }
192	
193	    // Guardrail: per-conversation reply cap → escalate instead of looping.
194	    const botCount = convo.messages.filter((m) => m.sender === "bot").length;
195	    const maxReplies = await getSettingInt("kb_bot_max_replies", 16);
196	    if (maxReplies > 0 && botCount >= maxReplies) {
197	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
198	      return;
199	    }
200	
201	    // Guardrail: platform-wide daily reply cap (soft cost ceiling). Over it, we
202	    // still answer — just from the token-free retrieval path (no paid call).
203	    let overDaily = false;
204	    const dailyCap = await getSettingInt("kb_bot_daily_cap", 1000);
205	    if (dailyCap > 0) {
206	      const since = new Date();
207	      since.setHours(0, 0, 0, 0);
208	      const used = await db.kbBotLog.count({
209	        where: { createdAt: { gte: since }, kind: { in: ["answer", "offer"] } },
210	      });
211	      overDaily = used >= dailyCap;
212	    }
213	
214	    const history = toHistory(convo.messages.slice(0, -1));
215	    const result = await kbAnswer(args.currentBody, {
216	      history,
217	      images: args.images,
218	      visitorName: firstName(convo.name),
219	      userId: convo.userId,
220	      noLlm: overDaily,
221	    });
222	
223	    // A live agent is ONLY brought in when the visitor explicitly asks for one
224	    // (humanIntent → kind "handoff"). The bot never offers or escalates on its own.
225	    if (result.kind === "handoff") {
226	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
227	      return;
228	    }
229	
230	    if (result.reply) {
231	      // Resolve any plan cards to render with this reply: the LLM signals them
232	      // with a hidden [[cards: key1, key2]] directive; the retrieval fallback
233	      // supplies result.cardKeys. Cards are looked up from the real catalog, so
234	      // the model can only ever pick keys — prices/features are never invented.
235	      const parsed = parseCardDirective(result.reply);
236	      const keys = [...(result.cardKeys ?? []), ...parsed.keys];
237	      const cards = keys.length ? getPlanCards(keys) : [];
238	      await db.chatMessage.create({
239	        data: {
240	          conversationId: convo.id,
241	          sender: "bot",
242	          body: parsed.body,
243	          cardsJson: cards.length ? JSON.stringify(cards) : null,
244	        },
245	      });
246	    }
247	    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
248	    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
249	    // admin KB dashboard shows the bot is broken instead of it failing silently.
250	    await db.kbBotLog
251	      .create({
252	        data: {
253	          visitorId: args.visitorId,
254	          conversationId: convo.id,
255	          question: args.currentBody.slice(0, 500),
256	          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
257	          matchedTitle: result.matchedTitle ?? null,
258	        },
259	      })
260	      .catch(() => {});
261	  } catch {
262	    /* assistant is non-essential — never fail the visitor's message on it */
263	  }
264	}
