1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
6	import { trustedClientIp } from "@/app/api/_lib/client-ip";
7	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
8	
9	export const runtime = "nodejs";
10	
11	/**
12	 * Image upload for <ChatWidget/>.
13	 *
14	 * POST /api/chat/upload  (multipart/form-data: visitorId, file, optional body,
15	 * optional name/email) — attaches an image to the visitor's OPEN conversation
16	 * (created if none), exactly like POST /api/chat but carrying an image.
17	 *
18	 * Authorization mirrors POST /api/chat: the conversation is scoped strictly by
19	 * the client-supplied `visitorId`, so a visitor can only ever attach to their
20	 * own thread. The image is validated by signature (not the client-declared
21	 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
22	 * Postgres. Per-IP rate limited.
23	 */
24	
25	function clip(v: unknown, max: number): string | null {
26	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
27	}
28	
29	export async function POST(req: Request) {
30	  const rl = checkRateLimit(`chat-upload:${trustedClientIp(req)}`, { max: 15, windowMs: 60_000 });
31	  if (!rl.ok) {
32	    return NextResponse.json(
33	      { error: "Too many uploads. Please slow down." },
34	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
35	    );
36	  }
37	
38	  let form: FormData;
39	  try {
40	    form = await req.formData();
41	  } catch {
42	    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
43	  }
44	
45	  const visitorId = clip(form.get("visitorId"), 100);
46	  const body = clip(form.get("body"), 5000) ?? "";
47	  const name = clip(form.get("name"), 120);
48	  const email = clip(form.get("email"), 200);
49	  const conversationId = clip(form.get("conversationId"), 40);
50	  const file = form.get("file");
51	
52	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
53	  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
54	  // Cheap guard before buffering the whole body into memory.
55	  if (file.size > MAX_ATTACHMENT_BYTES) {
56	    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
57	  }
58	
59	  const bytes = Buffer.from(await file.arrayBuffer());
60	  const check = validateImageBytes(bytes, file.type);
61	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
62	
63	  const user = await currentUser();
64	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
65	    user?.id ? [{ userId: user.id }] : [],
66	  );
67	
68	  // Continue the named conversation (if owned), else start a new one — mirrors
69	  // POST /api/chat.
70	  let convo = conversationId
71	    ? await db.chatConversation.findFirst({
72	        where: { id: conversationId, OR: ownedBy },
73	        select: { id: true, name: true, email: true },
74	      })
75	    : null;
76	
77	  if (!convo) {
78	    // Anonymous visitors must identify before starting (mirrors POST /api/chat).
79	    if (!user) {
80	      const nm = name ?? null;
81	      const em = email ?? null;
82	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
83	        return NextResponse.json(
84	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
85	          { status: 400 },
86	        );
87	      }
88	    }
89	    convo = await db.chatConversation.create({
90	      data: {
91	        visitorId,
92	        userId: user?.id ?? null,
93	        name: name ?? user?.name ?? null,
94	        email: email ?? user?.email ?? null,
95	      },
96	      select: { id: true, name: true, email: true },
97	    });
98	  }
99	
100	  const convoId = convo.id;
101	  await db.$transaction(async (tx) => {
102	    const msg = await tx.chatMessage.create({
103	      data: { conversationId: convoId, sender: "visitor", body },
104	    });
105	    await tx.chatAttachment.create({
106	      data: {
107	        messageId: msg.id,
108	        mime: check.mime,
109	        sizeBytes: check.bytes.length,
110	        data: new Uint8Array(check.bytes),
111	      },
112	    });
113	    await tx.chatConversation.update({
114	      where: { id: convoId },
115	      data: {
116	        status: "OPEN",
117	        unreadForAgent: true,
118	        lastMessageAt: new Date(),
119	        ...(user?.id ? { userId: user.id } : {}),
120	        ...(name && !convo!.name ? { name } : {}),
121	        ...(email && !convo!.email ? { email } : {}),
122	      },
123	    });
124	  });
125	
126	  // Let the assistant look at the image (Claude vision) and reply, before we
127	  // return — so the bot's answer rides back on this response. Best-effort.
128	  try {
129	    const { runAssistant } = await import("@/lib/kb-run");
130	    await runAssistant({
131	      conversationId: convoId,
132	      visitorId,
133	      currentBody: body,
134	      images: [{ mediaType: check.mime, dataB64: Buffer.from(check.bytes).toString("base64") }],
135	    });
136	  } catch {
137	    /* assistant is non-essential */
138	  }
139	
140	  const full = await db.chatConversation.findUnique({
141	    where: { id: convoId },
142	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
143	  });
144	
145	  return NextResponse.json(
146	    {
147	      conversation: full
148	        ? { id: full.id, status: full.status, name: full.name, email: full.email }
149	        : null,
150	      messages: (full?.messages ?? []).map((m) => ({
151	        id: m.id,
152	        sender: m.sender,
153	        body: m.body,
154	        createdAt: m.createdAt.toISOString(),
155	        attachment: m.attachment
156	          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
157	          : null,
158	      })),
159	    },
160	    { headers: NO_STORE_HEADERS },
161	  );
162	}
