// ---------------------------------------------------------------------------
// Account ACTION cards — the natural extension of the plan-card mechanism
// (lib/kb-plans.ts) for a real thing a tool call just found: a specific
// service, invoice, or ticket the signed-in customer owns. Same trust model as
// every other function in this file: the model may only ever supply an id it
// already read back from ITS OWN tool output in this conversation, and every
// lookup here is re-scoped to `userId` before anything is returned — a foreign
// or stale id simply resolves to nothing (no card), never another customer's
// service. The model can't invent working links here any more than it can
// invent plan prices in kb-plans.ts.
// ---------------------------------------------------------------------------

export type AccountActionCard = {
  type: "action";
  key: string;
  kind: "service" | "invoice" | "ticket";
  title: string;
  subtitle?: string;
  ctaLabel: string;
  ctaUrl: string;
};

const ACTION_LABELS: Record<AccountActionCard["kind"], string> = {
  service: "View service",
  invoice: "View invoice",
  ticket: "View ticket",
};

/**
 * Resolve one `[[action: type=…, id=…]]` directive (see lib/kb-run.ts's
 * parser) into a real, clickable card — or null if the id doesn't belong to
 * this customer (dropped silently; the reply text still stands on its own).
 * `id` is whatever the model copied from a prior tool result: an internal id
 * for a service/ticket (shown there as `[id]`), or the human invoice number
 * (shown there as `#1042`) for an invoice.
 */
export async function resolveActionCard(
  userId: string | null | undefined,
  kind: string,
  id: string,
  label?: string,
): Promise<AccountActionCard | null> {
  if (!userId || !id) return null;
  try {
    if (kind === "service") return await resolveServiceAction(userId, id, label);
    if (kind === "invoice") return await resolveInvoiceAction(userId, id, label);
    if (kind === "ticket") return await resolveTicketAction(userId, id, label);
    return null;
  } catch {
    return null; // a bad/foreign id is just dropped, never surfaced as an error card
  }
}

async function resolveServiceAction(userId: string, id: string, label?: string): Promise<AccountActionCard | null> {
  const server = await db.server.findFirst({ where: { id, userId }, select: { id: true, name: true, label: true, status: true, gamePlanId: true, nxcloudInstance: { select: { id: true } } } });
  if (server) {
    return {
      type: "action",
      key: `svc_${server.id}`,
      kind: "service",
      title: server.label || server.name,
      subtitle: `${serverType(server)} — ${server.status}`,
      ctaLabel: label?.trim() || ACTION_LABELS.service,
      ctaUrl: `/dashboard/servers/${server.id}`,
    };
  }
  const hosting = await db.hostingAccount.findFirst({ where: { id, userId }, select: { id: true, primaryDomain: true, status: true } });
  if (hosting) {
    return {
      type: "action",
      key: `svc_${hosting.id}`,
      kind: "service",
      title: hosting.primaryDomain,
      subtitle: `hosting — ${hosting.status}`,
      ctaLabel: label?.trim() || ACTION_LABELS.service,
      ctaUrl: `/dashboard/hosting/${hosting.id}`,
    };
  }
  const domain = await db.domain.findFirst({ where: { id, userId }, select: { id: true, name: true, status: true } });
  if (domain) {
    return {
      type: "action",
      key: `svc_${domain.id}`,
      kind: "service",
      title: domain.name,
      subtitle: `domain — ${domain.status}`,
      ctaLabel: label?.trim() || ACTION_LABELS.service,
      ctaUrl: `/dashboard/domains/${domain.id}`,
    };
  }
  const email = await db.emailSubscription.findFirst({ where: { id, userId }, select: { id: true, domainName: true, status: true } });
  if (email) {
    return {
      type: "action",
      key: `svc_${email.id}`,
      kind: "service",
      title: email.domainName,
      subtitle: `email — ${email.status}`,
      ctaLabel: label?.trim() || "Manage email",
      ctaUrl: `/dashboard/email`, // no per-subscription page; overview is the real route
    };
  }
  const volume = await db.volume.findFirst({ where: { id, userId }, select: { id: true, name: true, status: true } });
  if (volume) {
    return {
      type: "action",
      key: `svc_${volume.id}`,
      kind: "service",
      title: volume.name,
      subtitle: `volume — ${volume.status}`,
      ctaLabel: label?.trim() || "Manage storage",
      ctaUrl: `/dashboard/volumes`, // no per-volume page; overview is the real route
    };
  }
  return null;
}

async function resolveInvoiceAction(userId: string, idOrNumber: string, label?: string): Promise<AccountActionCard | null> {
  const asNumber = Number.parseInt(idOrNumber.replace(/^#/, ""), 10);
  const invoice = Number.isFinite(asNumber)
    ? await db.invoice.findFirst({ where: { userId, number: asNumber }, select: { id: true, number: true, status: true } })
    : await db.invoice.findFirst({ where: { userId, id: idOrNumber }, select: { id: true, number: true, status: true } });
  if (!invoice) return null;
  return {
    type: "action",
    key: `inv_${invoice.id}`,
    kind: "invoice",
    title: `Invoice #${invoice.number}`,
    subtitle: invoice.status,
    ctaLabel: label?.trim() || ACTION_LABELS.invoice,
    ctaUrl: `/dashboard/invoices/${invoice.id}`,
  };
}

async function resolveTicketAction(userId: string, id: string, label?: string): Promise<AccountActionCard | null> {
  const ticket = await db.ticket.findFirst({ where: { id, userId }, select: { id: true, subject: true, status: true } });
  if (!ticket) return null;
  return {
    type: "action",
    key: `tix_${ticket.id}`,
    kind: "ticket",
    title: ticket.subject,
    subtitle: ticket.status,
    ctaLabel: label?.trim() || ACTION_LABELS.ticket,
    ctaUrl: `/dashboard/support/${ticket.id}`,
  };
}

