/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
 *  the visible body (directive stripped) and the card keys. */
function parseCardDirective(reply: string): { body: string; keys: string[] } {
  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
  if (!m) return { body: reply, keys: [] };
  const keys = m[1]
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
  return { body, keys };
}

/** One parsed (not-yet-resolved) `[[action: type=…, id=…, label="…"]]` spec. */
type ActionSpec = { kind: string; id: string; label?: string };

/** Extract every hidden `[[action: ...]]` directive from a bot reply — the
 *  account-action-card sibling of `[[cards: ...]]` (see lib/kb-tools.ts's
 *  resolveActionCard for what these become). Attribute order doesn't matter;
 *  unrecognized attributes are ignored. Directives are stripped from the
 *  visible body regardless of whether they end up resolving to a real card. */
function parseActionDirectives(reply: string): { body: string; specs: ActionSpec[] } {
  const specs: ActionSpec[] = [];
  const re = /\[\[\s*action\s*:\s*([^\]]+)\]\]/gi;
  const body = reply
    .replace(re, (_full, attrsRaw: string) => {
      const attrs: Record<string, string> = {};
      // key=value pairs, comma-separated; value optionally double-quoted.
      const attrRe = /(\w+)\s*=\s*(?:"([^"]*)"|([^,]+))/g;
      let am: RegExpExecArray | null;
      while ((am = attrRe.exec(attrsRaw)) !== null) {
        attrs[am[1].toLowerCase()] = (am[2] ?? am[3] ?? "").trim();
      }
      if (attrs.type && attrs.id) {
        specs.push({ kind: attrs.type.toLowerCase(), id: attrs.id, label: attrs.label });
      }
      return "";
    })
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { body, specs };
}

type ChatCard = (PlanCard & { type: "plan" }) | AccountActionCard;

