import { test } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { stripCommentsAndStrings } from "./_source-tools.ts";
import {
  isStepActive,
  setBotStep,
  readBotStep,
  clearBotStep,
  BOT_STEP_TTL_MS,
  _resetBotStep,
} from "../lib/chat-bot-step.ts";

// ---------------------------------------------------------------------------
// Expiry predicate — mirrors chat-typing.ts's isTypingActive contract exactly,
// so a stalled/crashed model call can never leave a "Checking your billing…"
// label stuck on screen forever.
// ---------------------------------------------------------------------------

test("isStepActive: a fresh stamp is active", () => {
  const now = 1_000_000;
  assert.equal(isStepActive(now, now), true);
});

test("isStepActive: a stamp within the TTL is active", () => {
  const now = 1_000_000;
  assert.equal(isStepActive(now - (BOT_STEP_TTL_MS - 1), now), true);
});

test("isStepActive: a stamp at/after the TTL has expired", () => {
  const now = 1_000_000;
  assert.equal(isStepActive(now - BOT_STEP_TTL_MS, now), false);
  assert.equal(isStepActive(now - (BOT_STEP_TTL_MS + 5000), now), false);
});

test("isStepActive: absent / zero / future timestamps are never active", () => {
  const now = 1_000_000;
  assert.equal(isStepActive(undefined, now), false);
  assert.equal(isStepActive(0, now), false);
  assert.equal(isStepActive(now + 5000, now), false, "a future stamp is not treated as active");
});

// ---------------------------------------------------------------------------
// set/read/clear round-trip.
// ---------------------------------------------------------------------------

test("setBotStep is read back and expires on its own", () => {
  _resetBotStep();
  const id = randomUUID();
  const t0 = 5_000_000;

  setBotStep(id, "Checking your billing…", t0);
  assert.equal(readBotStep(id, t0), "Checking your billing…");

  // A later label for the same conversation overwrites the earlier one.
  setBotStep(id, "Finding your invoices…", t0 + 500);
  assert.equal(readBotStep(id, t0 + 500), "Finding your invoices…");

  // Past the TTL, the label is gone.
  assert.equal(readBotStep(id, t0 + 500 + BOT_STEP_TTL_MS), null);
});

test("readBotStep on an unknown conversation is null", () => {
  _resetBotStep();
  assert.equal(readBotStep(randomUUID()), null);
});

test("clearBotStep immediately removes the label, even inside the TTL window", () => {
  _resetBotStep();
  const id = randomUUID();
  const t0 = 1_000_000;
  setBotStep(id, "Pulling up current plans…", t0);
  assert.equal(readBotStep(id, t0), "Pulling up current plans…");
  clearBotStep(id);
  assert.equal(readBotStep(id, t0), null, "cleared immediately, not just after the TTL");
});

test("setBotStep ignores an empty conversationId or label", () => {
  _resetBotStep();
  setBotStep("", "Checking your billing…");
  setBotStep(randomUUID(), "");
  // Nothing should have been stored — both calls were no-ops.
  assert.equal(readBotStep(""), null);
});

// ---------------------------------------------------------------------------
// SOURCE TRIPWIRES — the signal must actually travel end to end: anthropic.ts's
// onStep hook → kb-llm.ts's label mapping → the GET poll → the widget's display.
// ---------------------------------------------------------------------------

function readSrc(rel: string): string {
  return stripCommentsAndStrings(readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8"));
}

test("askClaudeWithTools fires onStep right before each tool executes", () => {
  const src = readSrc("../lib/anthropic.ts");
  assert.match(src, /onStep\?\.\(block\.name\)/, "onStep is invoked with the tool name before execTool runs");
  // Must appear before execTool is awaited, not after (a step label announced
  // after the fact is not "live").
  const stepIdx = src.indexOf("onStep?.(block.name)");
  const execIdx = src.indexOf("await opts.execTool(block.name, block.input)");
  assert.ok(stepIdx >= 0 && execIdx >= 0 && stepIdx < execIdx, "onStep fires BEFORE execTool, not after");
});

test("kb-llm wires onStep to setBotStep, keyed by conversationId, and always clears it", () => {
  const src = readSrc("../lib/kb-llm.ts");
  assert.match(src, /onStep:\s*convoId\s*\?\s*\(toolName\)\s*=>\s*setBotStep\(convoId,\s*stepLabelFor\(toolName\)\)/);
  assert.match(src, /if\s*\(convoId\)\s*clearBotStep\(convoId\)/, "the step label is cleared once the turn ends");
});

