import { test } from "node:test";
import assert from "node:assert/strict";
import { createServer, type Server } from "node:http";
import { randomUUID } from "node:crypto";
import { askClaudeWithTools } from "../lib/anthropic.ts";

/**
 * Hermetic, real end-to-end proof that the "onStep" live-thinking hook (added
 * to askClaudeWithTools in lib/anthropic.ts) actually fires at the right time
 * and doesn't disturb the tool loop's own behavior — WITHOUT needing a funded
 * Anthropic API key. The official SDK reads `ANTHROPIC_BASE_URL` at client
 * construction time (node_modules/@anthropic-ai/sdk/client.js), so pointing it
 * at a tiny local HTTP server that plays back a scripted two-turn tool-use
 * conversation gives a real integration test of the request/response loop,
 * not just a mock of our own code.
 *
 * Script: turn 1 → the model "calls" two tools in one round; turn 2 → after
 * both tool_results are sent back, it returns final text with stop_reason
 * "end_turn". Asserts onStep fired for both tools, in order, before each
 * tool's execTool ran, and that the final text is returned unchanged.
 */

function messagesResponse(body: unknown) {
  return JSON.stringify(body);
}

async function withMockAnthropic(
  turns: object[],
  fn: (baseURL: string) => Promise<void>,
): Promise<void> {
  let call = 0;
  const server: Server = createServer((req, res) => {
    const chunks: Buffer[] = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => {
      const turn = turns[call] ?? turns[turns.length - 1];
      call++;
      res.writeHead(200, { "content-type": "application/json" });
      res.end(messagesResponse(turn));
    });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const addr = server.address();
  if (!addr || typeof addr === "string") throw new Error("failed to bind mock server");
  const baseURL = `http://127.0.0.1:${addr.port}`;
  const prevBaseURL = process.env.ANTHROPIC_BASE_URL;
  process.env.ANTHROPIC_BASE_URL = baseURL;
  try {
    await fn(baseURL);
  } finally {
    if (prevBaseURL === undefined) delete process.env.ANTHROPIC_BASE_URL;
    else process.env.ANTHROPIC_BASE_URL = prevBaseURL;
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }
}

test("onStep fires before each tool call, in order, and the final text is unaffected", async () => {
  const toolUseTurn = {
    id: "msg_1",
    type: "message",
    role: "assistant",
    model: "claude-test",
    content: [
      { type: "tool_use", id: "toolu_1", name: "check_platform_status", input: {} },
      { type: "tool_use", id: "toolu_2", name: "get_plans", input: { product: "vps" } },
    ],
    stop_reason: "tool_use",
    stop_sequence: null,
    usage: { input_tokens: 10, output_tokens: 5 },
  };
  const finalTurn = {
    id: "msg_2",
    type: "message",
    role: "assistant",
    model: "claude-test",
    content: [{ type: "text", text: "All systems are fine, and here's the VPS lineup." }],
    stop_reason: "end_turn",
    stop_sequence: null,
    usage: { input_tokens: 20, output_tokens: 8 },
  };

  await withMockAnthropic([toolUseTurn, finalTurn], async () => {
    const steps: string[] = [];
    const execOrder: string[] = [];
    const apiKey = `test-${randomUUID()}`; // unique per test: never reuses a cached client

    const text = await askClaudeWithTools(apiKey, {
      system: "test",
      messages: [{ role: "user", content: "is everything up, and what VPS plans do you have?" }],
      tools: [
        { name: "check_platform_status", description: "d", input_schema: { type: "object", properties: {} } },
        { name: "get_plans", description: "d", input_schema: { type: "object", properties: {} } },
      ],
      execTool: async (name) => {
        // onStep for THIS tool must already have fired by the time execTool runs.
        assert.ok(steps.includes(name), `onStep(${name}) must fire before execTool(${name})`);
        execOrder.push(name);
        return `${name}: ok`;
      },
      onStep: (toolName) => steps.push(toolName),
    });

    assert.deepEqual(steps, ["check_platform_status", "get_plans"], "onStep fired for both tools, in order");
    assert.deepEqual(execOrder, ["check_platform_status", "get_plans"]);
    assert.equal(text, "All systems are fine, and here's the VPS lineup.");
  });
});

test("omitting onStep entirely is completely unaffected (back-compat)", async () => {
  const finalTurn = {
    id: "msg_1",
    type: "message",
    role: "assistant",
    model: "claude-test",
    content: [{ type: "text", text: "Sure thing." }],
    stop_reason: "end_turn",
    stop_sequence: null,
    usage: { input_tokens: 5, output_tokens: 3 },
  };

  await withMockAnthropic([finalTurn], async () => {
    const apiKey = `test-${randomUUID()}`;
    const text = await askClaudeWithTools(apiKey, {
      system: "test",
      messages: [{ role: "user", content: "hi" }],
      tools: [],
      execTool: async () => "unused",
      // no onStep passed at all
    });
    assert.equal(text, "Sure thing.");
  });
});

