 *  (and, as a safety net, anyone whose `animationend` never fires for any
 *  reason) close immediately/promptly instead of getting stuck with an open
 *  panel that visually looks closed-in-progress forever. */
function closePanel() {
  const reduceMotion =
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduceMotion) {
    setOpen(false);
    return;
  }
  setClosing(true);
  window.setTimeout(() => {
    setOpen(false);
    setClosing(false);
  }, 260); // safety net slightly past panel-out's duration, in case onAnimationEnd is missed
}

