// Chat widget button/behavior audit against staging.nxeon.cloud, using the
// staging tree's own installed Playwright. Anonymous-visitor pass first
// (every widget affordance that doesn't need login), then a signed-in pass.
import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";

const BASE = "https://staging.nxeon.cloud";
const SHOT_DIR = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/shots";
await import("node:fs").then((fs) => fs.mkdirSync(SHOT_DIR, { recursive: true }));

function log(...a) { console.log(new Date().toISOString().slice(11, 19), ...a); }

const browser = await chromium.launch();

async function anonymousPass() {
  const ctx = await browser.newContext({ bypassCSP: true, viewport: { width: 1280, height: 900 } });
  const page = await ctx.newPage();
  page.on("console", (msg) => { if (msg.type() === "error") log("console error:", msg.text().slice(0, 200)); });
  page.on("pageerror", (err) => log("pageerror:", String(err).slice(0, 200)));

  await page.goto(BASE, { waitUntil: "domcontentloaded", timeout: 30000 });
  await page.waitForTimeout(1500);

  const bubble = page.getByRole("button", { name: /open chat/i });
  await bubble.waitFor({ state: "visible", timeout: 15000 });
  await page.screenshot({ path: `${SHOT_DIR}/01-bubble.png` });
  log("1. Bubble visible");

  await bubble.click();
  await page.waitForTimeout(500); // let panel-in animation settle
  await page.screenshot({ path: `${SHOT_DIR}/02-panel-open.png` });
  log("2. Panel opened (screenshot: panel-in animation frame + funnel chips)");

  // Funnel: root chips visible
  const pricingChip = page.getByRole("button", { name: /compare plans & pricing/i });
  await pricingChip.waitFor({ state: "visible", timeout: 5000 });
  log("3. Root funnel chips visible");
  await pricingChip.click();
  await page.waitForTimeout(400);
  const backChip = page.getByRole("button", { name: /back/i });
  const sharedChip = page.getByRole("button", { name: /^shared hosting$/i });
  await sharedChip.waitFor({ state: "visible", timeout: 5000 });
  await page.screenshot({ path: `${SHOT_DIR}/03-funnel-branch.png` });
  log("4. Funnel branch (pricing) chips visible, Back chip present:", await backChip.isVisible());
  await backChip.click();
  await page.waitForTimeout(300);
  const rootAgain = page.getByRole("button", { name: /compare plans & pricing/i });
  log("5. Back navigation returned to root:", await rootAgain.isVisible());

  // Menu toggle button (hides/shows the funnel)
  // First seed identity fields since anonymous — but don't send yet.
  const nameInput = page.getByPlaceholder("Your name*");
  const emailInput = page.getByPlaceholder("Email*");
  const hasIdentity = await nameInput.isVisible().catch(() => false);
  log("6. Anonymous identity fields present:", hasIdentity);
  if (hasIdentity) {
