    await page.getByLabel(/password/i).first().fill("AuditPass123!");
    await page.getByRole("button", { name: /log in|sign in/i }).first().click();
    await page.waitForTimeout(2500);
    log("13. Logged in, landed on:", page.url());
  } catch (e) {
